        ],
        "condition": {
          "all": [
            {"compare": "!=", "left": {"account": "$caller"}, "right": {"slot": "owner", "when": "before"}},
            {"compare": "!=", "left": {"slot": "paused", "when": "after"}, "right": {"slot": "paused", "when": "before"}}
          ]
        }
      }
    },
