        ],
        "condition": {
          "any": [
            {"compare": "!=", "left": {"slot": "owner", "when": "after"}, "right": {"slot": "owner", "when": "before"}},
            {"compare": "<", "left": {"slot": "caller_ledger", "when": "after"}, "right": {"slot": "caller_ledger", "when": "before"}}
          ]
        }
      }
    },
