          {"name": "paused", "kind": "view", "describe": "whether deposits are currently paused", "bind": {"view": {"method": "deposits_paused", "args": {}}}},
          {"name": "caller_ledger", "kind": "view", "describe": "the caller's recorded ledger balance in the vault", "bind": {"view": {"method": "balance_of", "args": {"account_id": "$caller"}}}},
          {"name": "contract_balance", "kind": "balance", "describe": "the contract account's real pooled NEAR balance", "bind": {"account": "$contract"}}
